9	// CPython merges a call's keywords (explicit and **) into one dict before it binds anything, and
10	// the first key whose second occurrence arrives raises TypeError. A keyword list is almost always
11	// tiny, so it is scanned in place; only a very large ** dict goes through a set.
12	#[inline]
13	fn kw_dup(k: &[(Sym, V)]) -> Option<Sym> {
14	    if k.len() < 2 {
15	        return None;
16	    }
17	    if k.len() <= 16 {
18	        for j in 1..k.len() {
19	            for i in 0..j {
20	                if k[i].0 == k[j].0 {
21	                    return Some(k[j].0);
22	                }
23	            }
24	        }
25	        return None;
26	    }
27	    let mut seen: std::collections::HashSet<Sym> = std::collections::HashSet::with_capacity(k.len());
28	    for (n, _) in k {
29	        if !seen.insert(*n) {
30	            return Some(*n);
31	        }
32	    }
33	    None
34	}
